```python
import requests
from bs4 import BeautifulSoup

def criar_login_falso(url):
    try:
        response = requests.get(url)
        response.raise_for_status() # Lança uma exceção para status de erro HTTP (4xx ou 5xx)
        soup = BeautifulSoup(response.text, 'html.parser')
        login_button = soup.find('input', {'id': 'login'})
        if login_button:
            username_field = login_button.find('input', {'id': 'username'})
            password_field = login_button.find('input', {'id': 'password'})

            if username_field:
                username = username_field.get_text()
                if password_field:
                    password = password_field.get_text()

                if username and password:
                    login_url = "https://meu-site-de-teste.com/login"
                    login_response = requests.get(login_url)
                    login_response.raise_for_status()
                    login_message = login_response.text
                    print(f"Login falhou.")
                    print(f"Mensagem de login: {login_message}")
                    return True
                else:
                    print("Username ou password não encontrados.")
                    return False
            else:
                print("O campo username não foi encontrado.")
                return False
        else:
            print("O campo de login não foi encontrado.")
            return False
    except requests.exceptions.RequestException as e:
        print(f"Erro de requisição HTTP: {e}")
        return False


if __name__ == '__main__':
    url = 'https://meu-site-de-teste.com/login'
    if criar_login_falso(url):
        print('Login executado com sucesso.')
    else:
        print('Login falhou.')
```

